<template>
  <el-popconfirm
    :title="title || t('common.confirmAction')"
    :confirm-button-text="confirmButtonText || t('common.confirm')"
    :cancel-button-text="cancelButtonText || t('common.cancel')"
    :confirm-button-type="confirmButtonType"
    @confirm="onConfirm"
  >
    <template #reference>
      <slot />
    </template>
  </el-popconfirm>
</template>

<script setup lang="ts">
import { useI18n } from 'vue-i18n'

withDefaults(
  defineProps<{
    title?: string
    confirmButtonText?: string
    cancelButtonText?: string
    confirmButtonType?: 'primary' | 'success' | 'warning' | 'danger' | 'info'
  }>(),
  {
    title: undefined,
    confirmButtonText: undefined,
    cancelButtonText: undefined,
    confirmButtonType: 'primary',
  }
)

const { t } = useI18n()

const emit = defineEmits<{
  confirm: []
}>()

function onConfirm() {
  emit('confirm')
}
</script>
